/* ================== PARAMETERS (SSMS) ================== */
DECLARE @StartDate NVARCHAR(20) = '2026-01-01';
DECLARE @EndDate   NVARCHAR(20) = '2026-12-31';
DECLARE @Whscode   NVARCHAR(50) = NULL;  -- NULL: All Warehouses, or specific WhsCode (e.g. 'W01')
DECLARE @StartItemCode NVARCHAR(50) = NULL;
DECLARE @EndItemCode   NVARCHAR(50) = NULL;

SELECT         tmp.Warehouse,         (         SELECT Whsname         FROM   owhs         WHERE  whscode=tmp.Warehouse        ) 'WH-name', 		        tmp.ItemCode,        tmp.ItemName,        T9.ItmsGrpCod AS ItemGroupCode,T10.ItmsGrpNam AS ItemGroupName,        T9.InvntryUom,                   SUM(tmp.BeginQty) AS [Opening Qty],        SUM(tmp.BeginBalance)[Opening Value],        SUM(tmp.InQty) AS [Input Qty],        SUM(tmp.InBalance) AS [Input Value],        SUM(tmp.OutQty) AS [Output Qty],        SUM(tmp.OutBalance) AS [Output Value],        (SUM(tmp.BeginQty) + SUM(tmp.InQty) - SUM(tmp.OutQty)) AS [Ending Qty],        (SUM(tmp.BeginBalance) + SUM(tmp.InBalance) - SUM(tmp.OutBalance)) AS [Ending Value]FROM    (         SELECT T0.ItemCode ItemCode,                T1.ItemName ItemName,                T0.Warehouse,                0 BeginQty,                0 BeginBalance,                0 InQty,                SUM(T0.TransValue) InBalance,                0 OutQty,                0 OutBalance         FROM   OINM T0         INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode         WHERE  (T0.[DocDate]>=@StartDate OR @StartDate IS NULL OR @StartDate=N'') AND (T0.[DocDate]<=@EndDate OR @EndDate IS NULL OR @EndDate=N'') AND T0.TransValue>0         GROUP BY T0.ItemCode,                T1.ItemName,                T0.Warehouse         UNION ALL         SELECT T0.ItemCode ItemCode,                T1.ItemName ItemName,                T0.Warehouse,                0 BeginQty,                0 BeginBalance,                0,                0,                0,                -SUM(T0.TransValue) OutBalance         FROM   OINM T0         INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode         WHERE  (T0.[DocDate]>=@StartDate OR @StartDate IS NULL OR @StartDate=N'') AND (T0.[DocDate]<=@EndDate OR @EndDate IS NULL OR @EndDate=N'') AND T0.TransValue<0         GROUP BY T0.ItemCode,                T1.ItemName,                T0.Warehouse         UNION ALL         SELECT T0.ItemCode ItemCode,                T1.ItemName ItemName,                T0.Warehouse,                0 BeginQty,                0 BeginBalance,                SUM(T0.InQty) InQty,                0,                SUM(T0.OutQty) OutQty,                0         FROM   OINM T0         INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode         WHERE  (T0.[DocDate]>=@StartDate OR @StartDate IS NULL OR @StartDate=N'') AND (T0.[DocDate]<=@EndDate OR @EndDate IS NULL OR @EndDate=N'')         GROUP BY T0.ItemCode,                T1.ItemName,                T0.Warehouse         UNION ALL         SELECT T0.ItemCode ItemCode,                T1.ItemName,                T0.Warehouse,                (SUM(T0.InQty) - SUM(T0.OutQty)) AS BeginQty,                SUM(T0.TransValue) AS BeginBalance,                0,                0,                0,                0         FROM   OINM T0         INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode         WHERE  T0.[DocDate]<@StartDate         GROUP BY T0.ItemCode,                T1.ItemName,                T0.Warehouse        ) tmp,        OITM T9,        OITB T10WHERE   tmp.ItemCode=T9.ItemCode and (tmp.Warehouse=@Whscode  or @Whscode  is null) and ((tmp.ItemCode>=@startItemcode or @startItemcode is null)   and (tmp.itemcode<=@enditemcode or @enditemcode is null))AND T9.ItmsGrpCod = T10.ItmsGrpCodGROUP BY tmp.ItemCode,        tmp.ItemName,        T9.Spec,    T9.InvntryUom,        tmp.Warehouse        ,T9.ItmsGrpCod,T10.ItmsGrpNamORDER BY tmp.ItemCode;